message:
{%- set facts = [] -%}
{%- for a in (doc.assets or [])[:8] -%}
{%- set _ = facts.append((a.asset or "Asset", (a.asset_name or "") ~ (" · S/N " ~ a.serial_number if a.serial_number else ""))) -%}
{%- endfor -%}
{%- if (doc.assets or [])|length > 8 -%}
{%- set _ = facts.append(("More", "and " ~ ((doc.assets|length) - 8) ~ " more")) -%}
{%- endif -%}
{%- if doc.accessories -%}
{%- set _ = facts.append(("Accessories", doc.accessories)) -%}
{%- endif -%}
{{ kiluth_email(
	title="Acknowledge your loan",
	kicker=doc.name,
	lines=[
		"Hi " ~ (doc.employee_name or doc.employee) ~ ". HR is lending you the equipment below.",
		"Open the agreement, check the items and terms, then click **I Acknowledge**. The loan isn't complete until you do.",
		"We log your account and the time as the record. If anything looks wrong, reply to this email and HR will fix it.",
	],
	facts=facts,
	hero="hero-leaf-rock.jpg",
	button="Review and acknowledge",
	href=frappe.utils.get_url_to_form(doc.doctype, doc.name),
) }}

{%- set facts = [
	("Returned by", doc.employee_name or doc.employee),
	("Date", frappe.utils.formatdate(doc.return_date, "d MMMM yyyy") if doc.return_date else ""),
] -%}
{%- for a in (doc.assets_returned or [])[:8] -%}
{%- set _ = facts.append((a.asset or "Asset", (a.asset_name or "") ~ (" · " ~ a.condition_on_return if a.condition_on_return else ""))) -%}
{%- endfor -%}
{%- if (doc.assets_returned or [])|length > 8 -%}
{%- set _ = facts.append(("More", "and " ~ ((doc.assets_returned|length) - 8) ~ " more")) -%}
{%- endif -%}
{%- set _ = facts.append(("Accessories", "All returned" if doc.all_accessories_returned else "Not all returned")) -%}
{%- if doc.damage_details -%}
{%- set _ = facts.append(("Damage", doc.damage_details)) -%}
{%- endif -%}
{{ kiluth_email(
	title="Equipment returned",
	kicker=doc.name,
	lines=[
		"**" ~ (doc.employee_name or doc.employee) ~ "** returned " ~ ((doc.assets_returned or [])|length) ~ " item" ~ ("" if (doc.assets_returned or [])|length == 1 else "s") ~ ".",
		"Check the condition photos and note any damage before you close the loan.",
	],
	facts=facts,
	hero="hero-leaf-rock.jpg",
	button="Open the return",
	href=frappe.utils.get_url_to_form(doc.doctype, doc.name),
) }}

{%- set facts = [
	("Borrower", doc.employee_name or doc.employee),
	("Signed", frappe.utils.formatdate(doc.date_signed, "d MMMM yyyy") if doc.date_signed else ""),
] -%}
{%- for a in (doc.assets or [])[:8] -%}
{%- set _ = facts.append((a.asset or "Asset", (a.asset_name or "") ~ (" · S/N " ~ a.serial_number if a.serial_number else ""))) -%}
{%- endfor -%}
{%- if (doc.assets or [])|length > 8 -%}
{%- set _ = facts.append(("More", "and " ~ ((doc.assets|length) - 8) ~ " more")) -%}
{%- endif -%}
{{ kiluth_email(
	title="Equipment loaned",
	kicker=doc.name,
	lines=[
		"**" ~ (doc.employee_name or doc.employee) ~ "** acknowledged the agreement and it's now submitted. " ~ ((doc.assets or [])|length) ~ " item" ~ ("" if (doc.assets or [])|length == 1 else "s") ~ " out on loan.",
	],
	facts=facts,
	hero="hero-leaf-rock.jpg",
	button="Open the agreement",
	href=frappe.utils.get_url_to_form(doc.doctype, doc.name),
) }}

{#- doc["items"], not doc.items: on a plain dict .items is the method -#}
{%- set items = doc["items"] or [] -%}
{%- set facts = [
	("Type", doc.material_request_type),
	("Requested by", doc.owner),
	("Needed by", frappe.utils.formatdate(doc.schedule_date, "d MMMM yyyy") if doc.schedule_date else ""),
] -%}
{%- for i in items[:8] -%}
{%- set _ = facts.append(("Item" if loop.first else "", (i.item_name or i.item_code) ~ " × " ~ ("%g"|format(i.qty or 0)) ~ (" " ~ i.uom if i.uom else ""))) -%}
{%- endfor -%}
{%- if items|length > 8 -%}
{%- set _ = facts.append(("", "and " ~ (items|length - 8) ~ " more")) -%}
{%- endif -%}
{{ kiluth_email(
	title="Material request",
	kicker=doc.name,
	lines=[
		"A material request for **" ~ (items|length) ~ " item" ~ ("" if items|length == 1 else "s") ~ "** was submitted. Review it and order what's needed.",
	],
	facts=facts,
	hero="hero-bark-moss.jpg",
	button="Open the request",
	href=frappe.utils.get_url_to_form(doc.doctype, doc.name),
) }}

{%- set details = (doc.description or "")|striptags|trim|truncate(600) -%}
{{ kiluth_email(
	title="HR problem report",
	kicker=doc.name,
	lines=[
		"**" ~ (doc.raised_by or doc.owner) ~ "** reported a problem: **" ~ doc.subject ~ "**",
	] + ([details] if details else []) + [
		"Read it and reply in the Portal.",
	],
	facts=[
		("Priority", doc.priority),
	],
	hero="hero-bark-moss.jpg",
	button="Open the report",
	href=frappe.utils.get_url_to_form(doc.doctype, doc.name),
) }}

{%- set who = doc.employee_name or doc.employee -%}
{%- set days = "%g"|format(doc.total_leave_days or 0) -%}
{{ kiluth_email(
	title="Leave request",
	kicker=doc.name,
	lines=[
		"**" ~ who ~ "** asked for **" ~ days ~ (" day" if days == "1" else " days") ~ "** of " ~ (doc.leave_type or "leave") ~ ".",
		"Approve or reject it in the Portal.",
	],
	facts=[
		("Leave type", doc.leave_type),
		("From", frappe.utils.formatdate(doc.from_date, "d MMMM yyyy")),
		("To", frappe.utils.formatdate(doc.to_date, "d MMMM yyyy")),
		("Days", days ~ (" (half day)" if doc.half_day else "")),
		("Reason", doc.description),
	],
	hero="hero-leaf-lit.jpg",
	button="Open the request",
	href=frappe.utils.get_url_to_form(doc.doctype, doc.name),
) }}
